/*
 * Pico 2 W — Serial Hello
 * Prints messages and counter to Serial Monitor
 */

int counter = 0;

void setup() {
  Serial.begin(115200);
  delay(1000);
  Serial.println("==================");
  Serial.println("  Pico 2 W Ready");
  Serial.println("  RP2350 @ 150MHz");
  Serial.println("==================");
}

void loop() {
  Serial.print("Hello from Pico 2 W! Counter: ");
  Serial.println(counter);
  counter++;
  delay(1000);
}
